const input = $input.first().json;
const company = String(input.company || input['Company'] || '').trim().replace(/\s+/g, ' ');
const objective = String(input.objective || input['Research objective'] || '').trim().replace(/\s+/g, ' ');
if (company.length < 2 || company.length > 200) throw new Error('Company must be 2-200 characters.');
if (objective.length < 20 || objective.length > 2000) throw new Error('Objective must be 20-2000 characters.');
const crypto = require('crypto');
const dedupe_key = crypto.createHash('sha256').update(company.toLowerCase() + '|' + objective.toLowerCase() + '|v1').digest('hex').slice(0, 32);
return [{ json: { company, objective, dedupe_key } }];

const row = $input.first().json;
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const SERIF = "Georgia,'Times New Roman',serif";
const MONO = "ui-monospace,'SF Mono',Menlo,monospace";
const INK = '#1a1a19', SOFT = '#44443f', MUTED = '#6e6e6a', HAIR = '#e8e8e6', ACC = '#d13415', GREEN = '#1e5b3e';

const page = (inner) => '<div style="max-width:760px;margin:0 auto;padding:56px 40px 72px;font-family:-apple-system,\'Helvetica Neue\',sans-serif;color:' + INK + '">' + inner + '</div>';

if (!row.report_json) {
  return [{ json: { html: page(
    '<p style="font-family:' + MONO + ';font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:' + MUTED + '"><span style="display:inline-block;width:7px;height:7px;background:' + ACC + ';margin-right:9px"></span>VendorProof</p>' +
    '<h1 style="font-family:' + SERIF + ';font-weight:400;font-size:38px;letter-spacing:-0.01em;margin:28px 0 14px">No report yet.</h1>' +
    '<p style="font-size:15px;line-height:1.6;color:' + SOFT + ';max-width:56ch">No completed assessment exists for this company and objective. If you submitted it just now, research may still be running — check back in a couple of minutes.</p>'
  ) } }];
}

const rep = JSON.parse(row.report_json);
const VC = { supported: GREEN, contradicted: ACC, insufficient_evidence: '#8a6a00' };
const VL = { supported: 'SUPPORTED', contradicted: 'CONTRADICTED', insufficient_evidence: 'INSUFFICIENT EVIDENCE' };

const counts = rep.findings.reduce((a,f)=>{ a[f.verification]=(a[f.verification]||0)+1; return a; },{});
const tally = Object.keys(VL).map(k => counts[k] ? '<span style="color:' + VC[k] + '">' + counts[k] + ' ' + VL[k] + '</span>' : null).filter(Boolean).join('<span style="color:' + HAIR + '">&nbsp;&nbsp;·&nbsp;&nbsp;</span>');

const reviewBanner = rep.requires_review
  ? '<div style="border-left:2px solid ' + ACC + ';padding:14px 18px;margin:28px 0;background:#faf0ed"><p style="font-family:' + MONO + ';font-size:12px;letter-spacing:.08em;color:' + ACC + ';margin:0">REVIEW REQUIRED — ' + esc((rep.review_reasons||[]).join(' · ')) + '</p></div>'
  : '';

const finding = f =>
  '<div style="padding:20px 0;border-bottom:1px solid ' + HAIR + '">' +
    '<div style="display:flex;justify-content:space-between;gap:20px;align-items:baseline">' +
      '<p style="font-size:15px;line-height:1.5;color:' + INK + ';margin:0;flex:1">' + esc(f.claim) + '</p>' +
      '<span style="font-family:' + MONO + ';font-size:11px;letter-spacing:.06em;color:' + (VC[f.verification]||MUTED) + ';white-space:nowrap">' + (VL[f.verification]||f.verification) + '</span>' +
    '</div>' +
    '<p style="font-family:' + MONO + ';font-size:11px;color:' + MUTED + ';margin:8px 0 0">' + esc(f.topic) + ' · severity ' + esc(f.severity) + '</p>' +
    (f.source_url ? '<p style="margin:10px 0 0;font-size:13px"><a href="' + esc(f.source_url) + '" style="color:' + SOFT + ';text-decoration:underline;text-underline-offset:3px">' + esc(f.source_title || f.source_url) + '</a></p>' : '<p style="margin:10px 0 0;font-family:' + MONO + ';font-size:11px;color:' + MUTED + '">NO SOURCE</p>') +
    (f.evidence ? '<blockquote style="margin:12px 0 0;padding:10px 0 10px 18px;border-left:1px solid ' + INK + ';font-family:' + SERIF + ';font-style:italic;font-size:14px;line-height:1.55;color:' + SOFT + '">' + esc(f.evidence) + '</blockquote>' : '') +
  '</div>';

const tr = rep.trace || {}; const us = rep.usage || {};
const traceLine = (tr.model_calls!=null) ? '<p style="font-family:' + MONO + ';font-size:11px;color:' + MUTED + ';margin-top:36px;letter-spacing:.04em">MODEL CALLS ' + tr.model_calls + ' · ROUNDS ' + tr.research_rounds + ' · SEARCHES ' + (us.searches||tr.searches||'—') + ' · VALIDATOR ' + esc(rep.validator_version||'v1') + '</p>' : '';

const html = page(
  '<p style="font-family:' + MONO + ';font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:' + MUTED + '"><span style="display:inline-block;width:7px;height:7px;background:' + ACC + ';margin-right:9px"></span>VendorProof · Verified Assessment</p>' +
  '<h1 style="font-family:' + SERIF + ';font-weight:400;font-size:46px;letter-spacing:-0.02em;line-height:1.05;margin:26px 0 10px">' + esc(rep.vendor) + '</h1>' +
  '<p style="font-family:' + SERIF + ';font-style:italic;font-size:17px;color:' + SOFT + ';margin:0 0 18px;max-width:60ch">' + esc(rep.objective) + '</p>' +
  '<p style="font-family:' + MONO + ';font-size:11px;color:' + MUTED + ';letter-spacing:.04em;margin:0">' + esc(String(rep.status||'').toUpperCase()) + ' · ' + esc(rep.generated_at||'') + '</p>' +
  reviewBanner +
  '<div style="border-top:1px solid ' + INK + ';margin:30px 0 0;padding-top:22px">' +
    '<p style="font-family:' + MONO + ';font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:' + MUTED + ';margin:0 0 12px">Assessment</p>' +
    '<p style="font-size:15px;line-height:1.65;color:' + SOFT + ';margin:0;max-width:64ch">' + esc(rep.assessment) + '</p>' +
  '</div>' +
  '<div style="margin-top:34px"><p style="font-family:' + MONO + ';font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:' + MUTED + ';margin:0 0 4px">Findings — ' + rep.findings.length + '</p>' +
  '<p style="font-family:' + MONO + ';font-size:12px;margin:10px 0 0;letter-spacing:.02em">' + tally + '</p></div>' +
  '<div style="margin-top:6px;border-top:1px solid ' + INK + '">' + rep.findings.map(finding).join('') + '</div>' +
  traceLine
);
return [{ json: { html } }];
